<script setup lang="ts">import{onMounted}from 'vue';import{loadSeries,seriesStore}from '../stores/series';import{loadRuns,runStore}from '../stores/runs';import{loadReleases,releaseStore}from '../stores/releases';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import RunTable from '../components/RunTable.vue';import SeriesTable from '../components/SeriesTable.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import{useRouter}from 'vue-router';const router=useRouter();const{error,execute}=useTask();const refresh=()=>execute(async()=>{await Promise.all([loadSeries(),loadRuns(),loadReleases()])});onMounted(refresh);</script><template><PageHeading index="01 / OVERVIEW" title="日配的下一程" subtitle="潮汐鲜花供应协作组 · 让需求判断拥有可复算的依据。"/><ErrorNotice :message="error" @retry="refresh"/><div class="overview"><section class="dispatch"><p class="eyebrow">观察 → 回测 → 发布</p><h2>每条曲线，<br>都从真实观测出发。</h2><p>以滚动窗口比较季节朴素法与指数平滑。先看误差，再讨论未来。</p><RouterLink to="/experiments" class="primary link-button">建立预测任务 ↗</RouterLink></section><section class="ledger"><div><b>{{seriesStore.items.length}}</b><span>日配序列</span></div><div><b>{{seriesStore.items.reduce((a,s)=>a+s.observation_count,0)}}</b><span>每日观测</span></div><div><b>{{runStore.items.length}}</b><span>预测档案</span></div><div><b>{{releaseStore.items.length}}</b><span>已发布建议</span></div></section></div><div class="section-heading"><h2>最近的预测档案</h2><RouterLink to="/experiments">全部任务 →</RouterLink></div><RunTable :items="runStore.items.slice(0,4)"/><div class="section-heading"><h2>城市日配序列</h2><span>数据来源可追溯</span></div><SeriesTable :items="seriesStore.items.slice(0,3)" @select="id=>router.push('/series?selected='+id)"/></template>
